param([string]$Project = "C:\Projects\xcliprank", [string]$RestoreBackup = "")
$ErrorActionPreference = "Stop"
$Project = [IO.Path]::GetFullPath($Project)
if (!(Get-Command node -ErrorAction SilentlyContinue)) { throw "Node.js is required. No source files changed." }
$tempDir = Join-Path ([IO.Path]::GetTempPath()) ("xclip-registration-recovery1000-" + [Guid]::NewGuid().ToString("N"))
[IO.Directory]::CreateDirectory($tempDir) | Out-Null
try {
  $bytes = [Convert]::FromBase64String("")
  $sha = [Security.Cryptography.SHA256]::Create()
  try { $hash = [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace("-", "").ToLowerInvariant() } finally { $sha.Dispose() }
  if ($hash -ne "7b081e78b05465babfaef7aa8b3a0682a063817b1ffcb3edd4f3f25014d73c02") { throw "Embedded install.cjs checksum failed. No source files changed." }
  [IO.File]::WriteAllBytes((Join-Path $tempDir "install.cjs"), $bytes)
  $bytes = [Convert]::FromBase64String("")
  $sha = [Security.Cryptography.SHA256]::Create()
  try { $hash = [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace("-", "").ToLowerInvariant() } finally { $sha.Dispose() }
  if ($hash -ne "e3b7aef90736eda30ed4bd49d4427d4274e521c28026653a6d6a7a074e606cab") { throw "Embedded payload.json checksum failed. No source files changed." }
  [IO.File]::WriteAllBytes((Join-Path $tempDir "payload.json"), $bytes)
  & node (Join-Path $tempDir "install.cjs") $Project $RestoreBackup
  if ($LASTEXITCODE -ne 0) { throw "Installation/check failed. Read the error above." }
} finally {
  $cleanupRoot = [IO.Path]::GetFullPath([IO.Path]::GetTempPath()).TrimEnd('\') + '\'
  $cleanupTarget = [IO.Path]::GetFullPath($tempDir)
  if (!$cleanupTarget.StartsWith($cleanupRoot, [StringComparison]::OrdinalIgnoreCase) -or !(Split-Path -Leaf $cleanupTarget).StartsWith('xclip-registration-recovery1000-')) { throw 'TEMP_CLEANUP_PATH_REFUSED' }
  if (Test-Path -LiteralPath $cleanupTarget) { Remove-Item -LiteralPath $cleanupTarget -Recurse -Force }
}
